  'tour.action.accessibility': 'Abrir Ajustes → Accesibilidad',
  'tour.step.welcome.title': 'Te damos la bienvenida a Foreman',
  'tour.step.welcome.body': 'Ejecuta agentes de programación en paralelo, cada uno en su propia rama y en su propia copia del repositorio. Todo se queda en este ordenador. Te enseñamos dónde está cada cosa.',
  'tour.step.addRepo.title': 'Añadir un repositorio',
  'tour.step.addRepo.body': 'Abre una carpeta que ya sea un repositorio git, clona uno de GitHub o usa Inicio rápido para crear uno nuevo. Haz clic derecho en un repositorio para ver sus ajustes: script de configuración, script de ejecución y comprobaciones.',
  'tour.step.addRepo.where': 'el botón + en la tira de iconos de repositorios',
  'tour.step.newWorkspace.title': 'Empezar un espacio de trabajo',
  'tour.step.newWorkspace.body': 'Cada espacio de trabajo es una rama nueva en su propio worktree, con sus propios puertos y terminal, así que los agentes nunca chocan. Pulsa {key} y describe la tarea; también admite imágenes.',
  'tour.step.newWorkspace.where': 'el botón Nuevo espacio de trabajo, cerca de arriba',
  'tour.step.needsYou.title': 'Te necesitan',
  'tour.step.needsYou.body': 'Con varios agentes en marcha, dejas de vigilarlos. Todo lo que espera por ti (una aprobación, una pregunta, un plan, un turno fallido) se reúne aquí y en Inicio, con un contador, una notificación y una insignia en la bandeja o la barra de menús. {next} salta al siguiente espacio de trabajo que te necesita; {jump}, a lo que te necesita en el chat actual.',
  'tour.step.needsYou.where': 'los filtros Todos, Te necesitan, En marcha y Fijados',
  'tour.step.layout.title': 'Dos formas de ver tu trabajo',
  'tour.step.layout.body': 'Tres paneles muestra un espacio de trabajo con sus cambios y la terminal al lado; es lo que tienes ahora. Mosaicos muestra los chats de varios espacios de trabajo en paralelo. Cambia cuando quieras con {palette} («Cambiar a mosaicos») o en Ajustes → Apariencia → Diseño de ventana.',
  'tour.step.automations.title': 'Plantillas y Automatizaciones',
  'tour.step.automations.body': 'Las plantillas son prompts con huecos para los detalles; usa las tuyas o las del repositorio. Las automatizaciones ejecutan una plantilla según una programación (a diario, cada semana, etc.) mientras Foreman esté abierto, con un calendario de lo que se ejecutó y lo que viene.',
  'tour.step.automations.where': 'Automatizaciones, arriba en la barra lateral',
  'tour.step.assistant.title': 'Pregunta al asistente',
  'tour.step.assistant.body': '¿No sabes dónde está algo? Pregunta aquí ({key}). Te lleva al ajuste exacto y nunca cambia nada. Funciona con Claude, así que inicia sesión primero en Claude.',
  'tour.step.assistant.where': 'Asistente, debajo de Automatizaciones',
  'tour.step.settings.title': 'Ajustes',
  'tour.step.settings.body': 'Accesibilidad: tamaño del texto, zoom, modos de color y avisos para lectores de pantalla. Agentes: inicia sesión y elige el predeterminado. MCP: los servidores del repositorio se aprueban en el panel de Git de un espacio de trabajo y los agentes reciben las herramientas propias de Foreman. Los espacios de trabajo remotos (experimentales, desactivados por defecto) ejecutan un espacio de trabajo en un sandbox en la nube.',
  'tour.step.settings.where': 'el engranaje en la tira de iconos de repositorios',
  'tour.step.help.title': 'Vuelve cuando quieras',
